CREATE POLICY "epi_risk_module_access" ON "epi_risk" AS RESTRICTIVE FOR ALL TO "app_runtime" USING (exists (select 1 from public.risks r where r.id = "epi_risk"."risk_id" and r.org_id = "epi_risk"."org_id")) WITH CHECK (exists (select 1 from public.risks r where r.id = "epi_risk"."risk_id" and r.org_id = "epi_risk"."org_id"));--> statement-breakpoint
