CREATE POLICY "risks_module_access" ON "risks" AS RESTRICTIVE FOR ALL TO "app_runtime" USING (exists (select 1 from public.ges g where g.id = "risks"."ges_id" and g.org_id = "risks"."org_id" and exists (select 1 from public.company_modules cm where cm.org_id = "risks"."org_id" and cm.company_id = g.company_id and cm.module = 'pgr' and cm.enabled = true))) WITH CHECK (exists (select 1 from public.ges g where g.id = "risks"."ges_id" and g.org_id = "risks"."org_id" and exists (select 1 from public.company_modules cm where cm.org_id = "risks"."org_id" and cm.company_id = g.company_id and cm.module = 'pgr' and cm.enabled = true)));